import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { ContextPruningTracker } from "./src/core/context-pruning/tracker.ts";
import { recoverablePrune } from "./src/core/context-pruning/recovery.ts";
import type { ToolRecord } from "./src/core/context-pruning/types.ts";

const root = mkdtempSync(join(tmpdir(), "dedup-regression-"));
afterAll(() => rmSync(root, { recursive: true, force: true }));
const output = "検索 café 🚀\\n".repeat(1000);
const args = { query: "example" };
const bytes = (value: string) => Buffer.byteLength(value);
function run(tracker: ContextPruningTracker, call: string) {
  return tracker.process(call, "code_search", args, output,
    recoverablePrune(root, "session", call, output));
}
function record(callId: string, prunedOutput: string | null): ToolRecord {
  return { callId, toolName: "code_search", args, originalOutput: output,
    prunedOutput, timestamp: 0 };
}

test("retains finalized text and originals; reload preserves byte accounting and baseline", () => {
  const tracker = new ContextPruningTracker(root);
  const first = run(tracker, "first");
  const second = run(tracker, "second");
  const third = run(tracker, "third");
  expect(second.modified).toBe(true);
  expect(third.output).toContain("callId: first");
  expect(tracker.getHistory().map(r => r.prunedOutput)).toEqual([null, second.output, third.output]);
  expect(tracker.getHistory().every(r => r.originalOutput === output)).toBe(true);
  expect(readFileSync(second.recoveryPath!, "utf8")).toBe(output);
  expect(second.bytesSaved).toBe(bytes(output) - bytes(second.output));
  expect(tracker.getStats()).toEqual({ totalCalls: 3, prunedCalls: 2,
    totalBytesSaved: second.bytesSaved + third.bytesSaved,
    estimatedContextBytes: bytes(first.output) + bytes(second.output) + bytes(third.output) });
  const loaded = new ContextPruningTracker(root);
  loaded.loadHistory(JSON.parse(JSON.stringify(tracker.getHistory())));
  expect(loaded.getStats()).toEqual(tracker.getStats());
  expect(run(loaded, "fourth").output).toContain("callId: first");
});

test("evicted full result is replaced by a new full baseline", () => {
  const tracker = new ContextPruningTracker(root, 2);
  run(tracker, "evict-first");
  run(tracker, "evict-second");
  run(tracker, "evict-third");
  const next = run(tracker, "evict-fourth");
  expect(next).toEqual({ output, modified: false, bytesSaved: 0 });
  expect(run(tracker, "evict-fifth").output).toContain("callId: evict-fourth");
});

test("selects latest matching full result and skips every shortened entry", () => {
  const tracker = new ContextPruningTracker(root);
  tracker.loadHistory([record("old", null), record("new", null), record("short", "pointer")]);
  expect(run(tracker, "latest").output).toContain("callId: new");
  tracker.loadHistory([record("short-only", "pointer")]);
  expect(run(tracker, "no-full").modified).toBe(false);
  tracker.loadHistory([record("short-equal", output)]);
  expect(run(tracker, "not-a-baseline").modified).toBe(false);
});

test("rejected finalization emits and records the full result as a baseline", () => {
  const tracker = new ContextPruningTracker(root);
  run(tracker, "before-reject");
  const rejected = tracker.process("rejected", "code_search", args, output,
    recoverablePrune(root, "", "rejected", output));
  expect(rejected).toEqual({ output, modified: false, bytesSaved: 0 });
  expect(tracker.getHistory()[1].prunedOutput).toBeNull();
  expect(tracker.getStats()).toEqual({ totalCalls: 2, prunedCalls: 0,
    totalBytesSaved: 0, estimatedContextBytes: 2 * bytes(output) });
  const loaded = new ContextPruningTracker(root);
  loaded.loadHistory(tracker.getHistory());
  expect(loaded.getStats()).toEqual(tracker.getStats());
  expect(run(loaded, "after-reject").output).toContain("callId: rejected");
});

test("recovery write failure and non-saving candidates leave originals intact", () => {
  const blocked = join(root, "blocked");
  writeFileSync(blocked, "file blocks directory creation");
  const tracker = new ContextPruningTracker(root);
  run(tracker, "failure-first");
  const result = tracker.process("failure-second", "code_search", args, output,
    recoverablePrune(blocked, "session", "failure-second", output));
  expect(result).toEqual({ output, modified: false, bytesSaved: 0 });
  expect(tracker.getHistory()[1].prunedOutput).toBeNull();
  const small = new ContextPruningTracker(root);
  const short = "hi";
  small.process("small-first", "code_search", args, short);
  const unchanged = small.process("small-second", "code_search", args, short,
    recoverablePrune(root, "session", "small-second", short));
  expect(unchanged).toEqual({ output: short, modified: false, bytesSaved: 0 });
  expect(small.getStats().prunedCalls).toBe(0);
});

test("safe identical calls still dedup; different args, outputs and side effects do not", () => {
  for (const tool of ["code_search", "mcp__aide__code_search", "Grep", "Glob"]) {
